INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Nutzt SLAAC immer einen DHCPv6-Server für die Autokonfiguration?', 2, '[{"text": "Nein", "correct": true, "because": "SLAAC ist serverlos"}, {"text": "Ja", "correct": false, "because": "Router reicht aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits benötigt SLAAC für die Interface-ID?', 3, '[{"text": "64", "correct": true, "because": "Standard für SLAAC"}, {"text": "48", "correct": false, "because": "Zu wenig"}, {"text": "128", "correct": false, "because": "Gesamtlänge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutzt Router-Advertisements für die Adresszuweisung?', 4, '[{"text": "SLAAC", "correct": true, "because": "Router liefert Präfix"}, {"text": "DHCPv6", "correct": false, "because": "Serverbasiert"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Nicht automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SLAAC ist serverlos. b) DHCPv6 vergibt DNS-Informationen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) Router-basiert, b) DHCPv6-Funktion"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Autokonfiguration mit SLAAC?', 5, '[{"text": "DHCP-Server", "correct": true, "because": "SLAAC ist serverlos"}, {"text": "Router-Advertisements", "correct": false, "because": "Kern von SLAAC"}, {"text": "Interface-ID", "correct": false, "because": "Teil der Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCPv6 ohne Router funktioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Server-Client-Kommunikation"}, {"text": "Nein", "correct": false, "because": "Router optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist schneller für kleine Netze?', 3, '[{"text": "SLAAC", "correct": true, "because": "Keine Serverlatenz"}, {"text": "DHCPv6", "correct": false, "because": "Serverabhängig"}, {"text": "Beides gleich", "correct": false, "because": "SLAAC simpler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale unterscheiden SLAAC und DHCPv6?', 5, '[{"text": "SLAAC: Serverlos", "correct": true, "because": "Nur Router nötig"}, {"text": "DHCPv6: Zentral verwaltet", "correct": true, "because": "Server steuert"}, {"text": "SLAAC: DNS-Zuweisung", "correct": false, "because": "Nur DHCPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) SLAAC nutzt /64-Subnetze. b) DHCPv6 ist serverlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, Server nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für SLAAC?', 4, '[{"text": "Router", "correct": false, "because": "Liefert Präfix"}, {"text": "Interface-ID", "correct": false, "because": "Erzeugt Adresse"}, {"text": "DHCP-Server", "correct": true, "because": "Serverlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DHCPv6 ohne Solicit starten?', 2, '[{"text": "Nein", "correct": true, "because": "Prozessbeginn"}, {"text": "Ja", "correct": false, "because": "Client initiiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für DHCPv6 essenziell?', 4, '[{"text": "Client", "correct": true, "because": "Startet Anfrage"}, {"text": "Server", "correct": true, "because": "Vergibt Adressen"}, {"text": "Router", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass SLAAC DNS-Informationen liefert. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Nur DHCPv6 oder RDNSS"}, {"text": "Ja", "correct": false, "because": "Erweiterung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei SLAAC?', 3, '[{"text": "Schnelligkeit", "correct": true, "because": "Keine Serverlatenz"}, {"text": "Zentrale Steuerung", "correct": false, "because": "DHCPv6-spezifisch"}, {"text": "Manuelle Eingriffe", "correct": false, "because": "Automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SLAAC nutzt RA. b) DHCPv6 braucht /64.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DHCPv6 gegenüber SLAAC?', 5, '[{"text": "Zentrale Verwaltung", "correct": true, "because": "Server steuert"}, {"text": "DNS-Zuweisung", "correct": true, "because": "Zusätzliche Infos"}, {"text": "Serverlosigkeit", "correct": false, "because": "SLAAC-Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei SLAAC unwichtig?', 3, '[{"text": "Router-Advertisements", "correct": false, "because": "Kern von SLAAC"}, {"text": "Interface-ID", "correct": false, "because": "Erzeugt Adresse"}, {"text": "Server-Konfiguration", "correct": true, "because": "Nicht nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht SLAAC eine /64-Präfixlänge?', 2, '[{"text": "Ja", "correct": true, "because": "Standard für SLAAC"}, {"text": "Nein", "correct": false, "because": "Funktioniert nicht anders"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCPv6 schneller als SLAAC ist?', 3, '[{"text": "Nein", "correct": true, "because": "Serverlatenz vs. RA"}, {"text": "Ja", "correct": false, "because": "SLAAC ist simpler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für zentrale Adressverwaltung?', 4, '[{"text": "DHCPv6", "correct": true, "because": "Serverbasiert"}, {"text": "SLAAC", "correct": false, "because": "Dezentral"}, {"text": "Beides", "correct": false, "because": "Unterschiedliche Ansätze"}]');
